<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Gallery,Media};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class GalleryController extends Controller{
 public function index(){return view('admin.galleries.index',['items'=>Gallery::withCount('media')->latest('event_date')->paginate(30)]);}
 public function create(){return view('admin.galleries.form',['item'=>new Gallery]);}
 public function store(Request $r){$gallery=Gallery::create($this->data($r));$this->photos($r,$gallery);return redirect()->route('admin.galleries.edit',$gallery)->with('ok','Альбом создан');}
 public function edit(Gallery $gallery){$gallery->load('media');return view('admin.galleries.form',['item'=>$gallery]);}
 public function update(Request $r,Gallery $gallery){$old=$gallery->cover;$d=$this->data($r,$gallery);$gallery->update($d);if(isset($d['cover'])&&$old&&$old!==$d['cover'])Storage::disk('public')->delete($old);$this->photos($r,$gallery);return back()->with('ok','Альбом сохранён');}
 public function mediaUpdate(Request $r,Gallery $gallery,Media $medium){abort_unless($gallery->media()->whereKey($medium->id)->exists(),404);$d=$r->validate(['alt'=>'nullable|max:255','sort'=>'required|integer|min:0|max:100000']);$medium->update(['alt'=>$d['alt']]);$gallery->media()->updateExistingPivot($medium->id,['sort'=>$d['sort']]);return back()->with('ok','Фото обновлено');}
 public function detach(Gallery $gallery,Media $medium){abort_unless($gallery->media()->whereKey($medium->id)->exists(),404);$gallery->media()->detach($medium->id);return back()->with('ok','Фото убрано из альбома. Файл остался в медиатеке.');}
 public function destroyMedia(Gallery $gallery,Media $medium){abort_unless($gallery->media()->whereKey($medium->id)->exists(),404);abort_if($medium->galleries()->where('galleries.id','!=',$gallery->id)->exists(),422,'Файл используется в другом альбоме. Сначала уберите его оттуда.');$gallery->media()->detach($medium->id);Storage::disk('public')->delete($medium->file);$medium->delete();return back()->with('ok','Фото и файл удалены');}
 public function destroy(Gallery $gallery){if($gallery->cover)Storage::disk('public')->delete($gallery->cover);$gallery->media()->detach();$gallery->delete();return back();}
 private function data(Request $r,?Gallery $item=null){$d=$r->validate(['title'=>'required|max:255','description'=>'nullable','event_date'=>'nullable|date','cover'=>'nullable|image|max:10240']);$base=Str::slug($r->input('slug')?:$d['title'])?:'gallery';$slug=$base;$i=2;while(Gallery::where('slug',$slug)->when($item,fn($q)=>$q->where('id','!=',$item->id))->exists())$slug=$base.'-'.$i++;$d['slug']=$slug;if($r->hasFile('cover'))$d['cover']=$r->file('cover')->store('galleries/covers','public');$d['is_published']=$r->boolean('is_published');return $d;}
 private function photos(Request $r,Gallery $gallery):void{$r->validate(['photos.*'=>'image|max:15360|mimes:jpg,jpeg,png,webp,avif']);$sort=(int)($gallery->media()->max('gallery_media.sort')??-1)+1;foreach($r->file('photos',[]) as $file){$path=$file->store('galleries/'.date('Y/m'),'public');$media=Media::create(['name'=>$file->getClientOriginalName(),'file'=>$path,'mime'=>$file->getMimeType(),'size'=>$file->getSize(),'alt'=>pathinfo($file->getClientOriginalName(),PATHINFO_FILENAME),'collection'=>'gallery']);$gallery->media()->attach($media->id,['sort'=>$sort++]);}}
}